package com.chx.notification.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="sent_notifications") public class SentNotification { @Id @GeneratedValue private UUID id; private UUID eventId; private String recipientEmail; private String subject; @Column(columnDefinition="text") private String body; private Instant sentAt; protected SentNotification(){} public SentNotification(UUID eventId,String email,String subject,String body,Instant at){this.eventId=eventId;recipientEmail=email;this.subject=subject;this.body=body;sentAt=at;} public UUID getId(){return id;} public String getRecipientEmail(){return recipientEmail;} public String getSubject(){return subject;} public String getBody(){return body;} public Instant getSentAt(){return sentAt;} }
